// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C("", 0, address(this)); }

    function testFuzz_property(address taker, address to) public {
        vm.assume(taker != address(0));
        vm.assume(to != address(0));

        uint256 makerPk = 1;
        address maker = vm.addr(makerPk);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: true,
            isLong: true,
            baseAsset: address(this),
            strike: 0,
            premium: 0,
            duration: 1 days,
            expiration: block.timestamp + 1,
            nonce: 0,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(makerPk, orderHash);
        bytes memory sig = abi.encodePacked(r, s, v);

        uint256[] memory noFloorIds = new uint256[](0);
        vm.prank(taker);
        uint256 positionId = c.fillOrder(order, sig, noFloorIds);

        // General rule: any successful transferFrom(from, to, id) must make ownerOf(id) == to.
        vm.prank(taker);
        c.transferFrom(taker, to, positionId);

        assertTrue(c.ownerOf(positionId) == to);
    }
}

