pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    TokenMock token;

    function setUp() public {
        c = new C("", 0, address(this));
        token = new TokenMock();
    }

    function testFuzz_property(
        uint256 sk,
        bool isCall,
        bool isLong,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 nonce
    ) public {
        sk = bound(sk, 1, type(uint256).max - 1);
        address maker = vm.addr(sk);
        duration = bound(duration, 0, 10_000 days - 1);
        uint256 expiration = block.timestamp + 1000;
        strike = bound(strike, 0, 1e30);
        premium = bound(premium, 0, 1e30);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        bytes32 orderHash = c.hashOrder(order);
        (uint8 v, bytes32 r, bytes32 s) = vm.sign(sk, orderHash);
        bytes memory signature = abi.encodePacked(r, s, v);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        c.fillOrder(order, signature, floorAssetTokenIds);

        uint256 positionId = uint256(c.hashOppositeOrder(order));
        bytes32 posHash = c.hashOppositeOrder(order);

        assertTrue(
            c.ownerOf(positionId) == address(this) && c.ownerOf(uint256(orderHash)) == maker && uint256(posHash) == positionId,
            "minted positions must be owned by their recipients"
        );
    }
}

contract TokenMock {
    function transferFrom(address, address, uint256) external returns (bool) {
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        return true;
    }

    function approve(address, uint256) external returns (bool) {
        return true;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C("", 0, address(this));
    }

    function testFuzz_property(uint256 nonce, uint256 strike) public {
        vm.assume(nonce < 10 ** 30);
        vm.assume(strike < 10 ** 30);

        // Adversarial environment: helper acts as the ERC1271 maker/signer AND as a
        // contract-valued baseAsset whose low-level token calls "succeed".
        SignerToken helper = new SignerToken();

        vm.warp(1000);

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        C.Order memory order = C.Order({
            maker: address(helper),
            isCall: true,
            isLong: true,
            baseAsset: address(helper),
            strike: strike,
            premium: 0,
            duration: 100,
            expiration: 2000,
            nonce: nonce,
            whitelist: whitelist,
            floorTokens: floorTokens,
            erc20Assets: erc20Assets,
            erc721Assets: erc721Assets
        });

        uint256 positionId = c.fillOrder(order, "", floorAssetTokenIds);

        // General rule: the recipient of a freshly filled position is its true owner
        // and can therefore transfer that position to the burn address.
        vm.prank(address(this));
        bool ok;
        try c.transferFrom(address(this), address(0xdead), positionId) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

/// Minimal helper: any call returns 0x1626ba7e (32 bytes). This satisfies
/// SignatureChecker's ERC1271 magic-value check as `maker`, and satisfies
/// SafeTransferLib's token-success checks as `baseAsset` (nonzero bool return).
contract SignerToken {
    fallback() external returns (bytes32) {
        return 0x1626ba7e00000000000000000000000000000000000000000000000000000000;
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test, IERC1271Sig {
    C c;
    MockERC20 token;

    function setUp() public {
        c = new C("", 0, address(this));
        token = new MockERC20();
    }

    function testFuzz_property(uint256 strike, uint256 premium, uint256 duration, uint256 nonce, address recipient) public {
        vm.assume(recipient != address(0) && recipient != address(this));
        strike = bound(strike, 1, 1e30);
        premium = bound(premium, 1, 1e30);
        duration = bound(duration, 1, 9999 days);

        address[] memory emptyAddrs = new address[](0);
        C.ERC20Asset[] memory noErc20 = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory noErc721 = new C.ERC721Asset[](0);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: true,
            baseAsset: address(token),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: block.timestamp + 1,
            nonce: nonce,
            whitelist: emptyAddrs,
            floorTokens: emptyAddrs,
            erc20Assets: noErc20,
            erc721Assets: noErc721
        });

        // The test contract itself is the maker and implements IERC1271,
        // so SignatureChecker accepts our "signature".
        bytes memory sig = new bytes(65);
        uint256[] memory noFloorIds = new uint256[](0);

        c.fillOrder(order, sig, noFloorIds);

        uint256 makerId = uint256(c.hashOrder(order));
        uint256 takerId = uint256(c.hashOppositeOrder(order));

        uint256 beforeSum = c.balanceOf(address(this)) + c.balanceOf(recipient);

        // Drive c through transferFrom (owner is this contract).
        c.transferFrom(address(this), recipient, takerId);

        // General rule: a transfer conserves the balance count across the two parties.
        assertTrue(c.balanceOf(address(this)) + c.balanceOf(recipient) == beforeSum);
    }

    function isValidSignature(bytes32, bytes memory) external pure returns (bytes4) {
        return this.isValidSignature.selector;
    }
}

interface IERC1271Sig {
    function isValidSignature(bytes32 hash, bytes memory signature) external view returns (bytes4);
}

contract MockERC20 {
    function approve(address, uint256) external pure returns (bool) {
        return true;
    }

    function transfer(address, uint256) external pure returns (bool) {
        return true;
    }

    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
